fn get_or_default(opt: Option[Int], default: Int) -> Int {
  return match opt {
    Some(v) => v,
    None => default,
  };
}

fn get_or_panic(opt: Option[Int]) -> Int
  requires: opt.is_some();
{
  return opt.unwrap();
}

fn main() -> Int {
  let a: Option[Int] = Some(42);
  let b: Option[Int] = None();
  let x = get_or_panic(a);
  let y = get_or_default(b, 0);
  return x + y;
}
